#include "../명명/기계연결이름.h"
/* Small native runtime for jaot's explicitly checked static Java subset. */
#include "호출.h"
#include "파일규약.h"
typedef unsigned long مەکینه_وشە;
static مەکینه_وشە 동적기억공간[8192];static unsigned 사용량;
void 자바실패(void){const char دەق[]="AOT runtime error\n";ڕایت_کردن_فایل_دەیتا(2,دەق,sizeof(دەق)-1);사용자호출(6,1,0,0,0,0,0);for(;;){}}
void 자바쌓기(مەکینه_وشە *ستاك_هەمارگە,int *깊이,مەکینه_وشە نرخ){if(*깊이<0||*깊이>=128)자바실패();ستاك_هەمارگە[(*깊이)++]=نرخ;}
مەکینه_وشە 자바꺼내기(مەکینه_وشە *ستاك_هەمارگە,int *깊이){if(*깊이<=0||*깊이>128)자바실패();return ستاك_هەمارگە[--*깊이];}
مەکینه_وشە 자바배열(int 개수){if(개수<0||(unsigned)개수+1>8192-사용량)자바실패();مەکینه_وشە*자료위치=동적기억공간+사용량;사용량+=개수+1;자료위치[0]=개수;return (مەکینه_وشە)자료위치;}
مەکینه_وشە *자바색인(مەکینه_وشە شت_سەرچاوە,int 개수){مەکینه_وشە*자료위치=(مەکینه_وشە*)شت_سەرچاوە;if(!자료위치||개수<0||(مەکینه_وشە)개수>=자료위치[0])자바실패();return 자료위치+개수+1;}
int 자바길이(مەکینه_وشە شت_سەرچاوە){if(!شت_سەرچاوە)자바실패();return *(مەکینه_وشە*)شت_سەرچاوە;}
int 자바나누기(int پۆوتانی_x,int 세로좌표,int 나머지){if(!세로좌표)자바실패();if(پۆوتانی_x==(-2147483647-1)&&세로좌표==-1)return 나머지?0:پۆوتانی_x;return 나머지?پۆوتانی_x%세로좌표:پۆوتانی_x/세로좌표;}
static unsigned درێژی_نرخ(const char*رست_دەیتا){unsigned 개수=0;if(!رست_دەیتا)자바실패();while(رست_دەیتا[개수])개수++;return 개수;}
void 자바출력(مەکینه_وشە 자료위치,int 수치,int 줄바꿈){
    if(수치){char 둘째값[16];unsigned 개수=0;int نرخ=(int)자료위치;unsigned 부호없는값=نرخ<0?0-(unsigned)نرخ:نرخ;do{둘째값[개수++]='0'+부호없는값%10;부호없는값/=10;}while(부호없는값);if(نرخ<0)둘째값[개수++]='-';while(개수)ڕایت_کردن_فایل_دەیتا(1,둘째값+--개수,1);}
    else{const char*رست_دەیتا=자료위치?(const char*)자료위치:"null";ڕایت_کردن_فایل_دەیتا(1,رست_دەیتا,درێژی_نرخ(رست_دەیتا));}if(줄바꿈)ڕایت_کردن_فایل_دەیتا(1,"\n",1);
}
مەکینه_وشە 자바파일쓰기(مەکینه_وشە گوزەر,مەکینه_وشە نرخ){const char*رست_دەیتا=(const char*)نرخ;unsigned 개수=درێژی_نرخ(رست_دەیتا);int فایل_دەسک=کردنەوە_فایل((const char*)گوزەر,쓰기전용|없으면만들기|내용비우기,0600);if(فایل_دەسک<0)자바실패();int 반환값=ڕایت_کردن_فایل_دەیتا(فایل_دەسک,رست_دەیتا,개수);داخستن_فایل(فایل_دەسک);if(반환값!=(int)개수)자바실패();return 0;}
مەکینه_وشە 자바파일읽기(مەکینه_وشە گوزەر){int فایل_دەسک=کردنەوە_فایل((const char*)گوزەر,تەنیا_دەخوێنرێتەوە_نرخ,0);if(فایل_دەسک<0)자바실패();int 개수=فایل_گۆڕینی_ئەندازە(فایل_دەسک);if(개수<0||개수>16384||(unsigned)(개수+8)/8>8192-사용량)자바실패();char*자료위치=(char*)(동적기억공간+사용량);사용량+=(개수+8)/8;int 반환값=파일자료읽기(فایل_دەسک,자료위치,개수);داخستن_فایل(فایل_دەسک);if(반환값!=개수)자바실패();자료위치[개수]=0;return (مەکینه_وشە)자료위치;}
